# ----------------- Pydantic Schemas -----------------
class TestItem(BaseModel):
    __test__ = False
    name: str = Field(description="Name of the medical test or parameter")
    value: str = Field(description="Observed value from the report")
    unit: Optional[str] = Field(default="", description="Measurement unit (e.g., mg/dL, %)")
    reference_range: Optional[str] = Field(default="", description="Normal reference range provided in the document")
    status: Literal["normal", "watch", "urgent", "unknown"] = Field(
        default="unknown",
        description="Comparison status against provided reference range"
    )
    meaning: str = Field(default="", description="Simple, plain-language explanation of what this test measures")
    confidence_or_uncertainty: str = Field(
        default="Extracted directly from visible text",
        description="Confidence note or OCR uncertainty mention"
    )

class ExtractedMedicine(BaseModel):
    name: str = Field(description="Name of prescribed medicine")
    dose: str = Field(default="", description="Strength or dosage (e.g. 500mg, 1 tablet)")
    frequency: str = Field(default="Once daily", description="Frequency instructions (e.g. Once daily, Twice daily)")
    timing: str = Field(default="morning", description="Slots: morning, afternoon, night, or combination")
    food_instruction: str = Field(default="After Food", description="Before Food, After Food, or With Food")
    duration: Optional[str] = Field(default="", description="Prescribed duration (e.g. 5 days, 30 days)")

class ReportExplanation(BaseModel):
    summary: str = Field(description="Clear, compassionate overall explanation of the medical document")
    tests: List[TestItem] = Field(default_factory=list, description="Extracted and evaluated test items")
    medicines: List[ExtractedMedicine] = Field(default_factory=list, description="Extracted prescription medications")
    doctor_questions: List[str] = Field(default_factory=list, description="Helpful, non-prescriptive questions to ask the doctor")
    food_tips: List[str] = Field(default_factory=list, description="Cautious, gentle dietary and lifestyle suggestions")
    disclaimer: str = Field(default=MANDATORY_DISCLAIMER, description="Mandatory safety disclaimer")
    report_date: Optional[str] = Field(default="", description="Date of the report if visible")
    doctor_name: Optional[str] = Field(default="", description="Doctor name if visible")
    facility_name: Optional[str] = Field(default="", description="Hospital, clinic or laboratory name")
    is_demo: bool = Field(default=False, description="Indicates if synthetic demo data was used")

