# ----------------- Claude AI Live Integration -----------------
def analyze_medical_document(
    image_bytes_list: List[bytes],
    mime_type: str = "image/png",
    language: str = "en",
    difficulty: str = "Simple"
) -> ReportExplanation:
    """
    Analyzes medical report images or PDFs using Claude Vision API.
    Falls back gracefully to synthetic demo mode if API key is not configured or on network error.
    """
    if IS_DEMO_MODE or not image_bytes_list:
        logger.info("Demo mode active or no images provided. Returning safe synthetic report extraction.")
        return get_synthetic_report_data(language=language, difficulty=difficulty)

    try:
        import anthropic
        client = anthropic.Anthropic(api_key=ANTHROPIC_API_KEY)

        # Build prompt enforcing strict medical safety guidelines
        prompt = f"""
You are an expert, compassionate healthcare document reader assisting elderly parents and their adult children.
Carefully inspect the provided medical report document.

Target Audience & Language:
- Preferred Language: {language} (Translate your output fields into this language if 'hi' for Hindi or 'te' for Telugu, or 'en' for English).
- Explanation Complexity: {difficulty} (Simple = gentle, clear, no dense medical jargon; Detailed = includes clinical context while remaining accessible).

CRITICAL MEDICAL SAFETY RULES:
1. Explain medical terminology in understandable, reassuring language.
2. Compare test values ONLY with reference ranges explicitly visible in the document.
3. If a value has no visible reference range, mark status as 'unknown'.
4. Clearly distinguish missing data from normal results.
5. NEVER diagnose any disease or prescribe medical treatment.
6. NEVER recommend changing or stopping prescribed medicines.
7. Do NOT treat AI severity labels as a clinical diagnosis.
8. Recommend prompt professional consultation for concerning results.
9. If acute emergency symptoms are described, direct the user to emergency medical services.
10. Return strictly valid JSON conforming to the requested schema. Do NOT wrap in markdown backticks or explanation text outside the JSON.

JSON Schema:
{{
  "summary": "Compassionate summary of the document",
  "report_date": "YYYY-MM-DD or visible date",
  "doctor_name": "Doctor name if visible",
  "facility_name": "Hospital, clinic or lab name if visible",
  "tests": [
    {{
      "name": "Test Name",
      "value": "Observed Value",
      "unit": "Unit",
      "reference_range": "Document reference range",
      "status": "normal, watch, urgent, or unknown",
      "meaning": "Plain language explanation",
      "confidence_or_uncertainty": "OCR confidence or note"
    }}
  ],
  "medicines": [
    {{
      "name": "Medicine name",
      "dose": "Dose",
      "frequency": "Frequency",
      "timing": "morning, afternoon, night, or combination",
      "food_instruction": "Before Food, After Food, or With Food",
      "duration": "Duration"
    }}
  ],
  "doctor_questions": ["Question 1", "Question 2"],
  "food_tips": ["Cautious lifestyle tip 1", "Tip 2"],
  "disclaimer": "{MANDATORY_DISCLAIMER if language == 'en' else MANDATORY_DISCLAIMER_HI if language == 'hi' else MANDATORY_DISCLAIMER_TE}"
}}
"""

        # Prepare messages content with images
        content_items = []
        for img_bytes in image_bytes_list[:5]:  # limit to max 5 pages
            b64_data = base64.b64encode(img_bytes).decode("utf-8")
            content_items.append({
                "type": "image",
                "source": {
                    "type": "base64",
                    "media_type": mime_type,
                    "data": b64_data
                }
            })
        content_items.append({"type": "text", "text": prompt})

        response = client.messages.create(
            model=CLAUDE_MODEL,
            max_tokens=3500,
            temperature=0.1,
            messages=[{"role": "user", "content": content_items}]
        )

        # Parse text content from response
        response_text = ""
        for block in response.content:
            if hasattr(block, "text"):
                response_text += block.text

        # Extract and parse JSON
        cleaned_json = response_text.strip()
        if cleaned_json.startswith("```json"):
            cleaned_json = cleaned_json[7:]
        if cleaned_json.startswith("```"):
            cleaned_json = cleaned_json[3:]
        if cleaned_json.endswith("```"):
            cleaned_json = cleaned_json[:-3]
        cleaned_json = cleaned_json.strip()

        parsed_data = json.loads(cleaned_json)
        validated = ReportExplanation.model_validate(parsed_data)
        validated.is_demo = False
        return validated

    except ValidationError as ve:
        logger.error(f"Pydantic schema validation error on Claude response: {ve}")
        fallback = get_synthetic_report_data(language=language, difficulty=difficulty)
        fallback.summary += f" (Note: Live AI output required schema correction: {str(ve)[:120]})"
        return fallback
    except Exception as e:
        logger.error(f"Error calling Claude API: {e}. Falling back to demo mode.")
        fallback = get_synthetic_report_data(language=language, difficulty=difficulty)
        fallback.summary += f" (Live AI Notice: Using demo mode due to connection/API message: {str(e)[:100]})"
        return fallback
